def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Step 1: Identify pairs (p, q) such that p + q = 800, p < q, and both are odd primes.
all_pairs_pq = []
for p in range(3, 400, 2):
    if is_prime(p):
        q = 800 - p
        if q > p and is_prime(q):
            all_pairs_pq.append((p, q))

# Restricting search to the first 5 pairs for computational feasibility
TEST_LIMIT_PQS = 5 
pairs_to_test = all_pairs_pq[:TEST_LIMIT_PQS]

# Setting a much smaller limit for r
R_LIMIT = 200 

results = {}

print(f"Testing the first {len(pairs_to_test)} pairs (p, q) up to r <= {R_LIMIT}.")

for p, q in pairs_to_test:
    found_r = []

    # Start searching r from the next prime after q
    r = q + 1
    while r <= R_LIMIT:
        if is_prime(r) and r > q:
            # Check the required primality conditions
            P1 = p + q + r  # = 800 + r
            P2 = q + r - p
            P3 = r + p - q

            if is_prime(P1) and is_prime(P2) and is_prime(P3):
                found_r.append(r)

            r += 1

    if found_r:
        # Store the largest found r for this pair
        results[(p, q)] = max(found_r)
        print(f"Found maximum possible r for ({p}, {q}): {max(found_r)}")
